-- SEAMUN I 2027 allocation matrix (workbook 8).
-- Adds missing delegate seats and updates placard codes to SEAMUN-2027-* values.
-- Preserves user_id. Leaves dais seats and assigned duplicate countries untouched.

BEGIN;

CREATE TEMP TABLE _matrix8 (
  new_id uuid,
  conference_id uuid,
  country text,
  code text
) ON COMMIT DROP;


SELECT m.new_id, m.conference_id, NULL, m.country
FROM _matrix8 m
WHERE NOT EXISTS (
  SELECT 1
  FROM public.allocations a
  WHERE a.conference_id = m.conference_id
    AND lower(btrim(a.country)) = lower(btrim(m.country))
);

WITH ranked AS (
  SELECT
    a.id AS allocation_id,
    m.code,
    row_number() OVER (
      PARTITION BY a.conference_id, lower(btrim(a.country))
      ORDER BY (a.user_id IS NULL) DESC, a.id
    ) AS rn
  FROM public.allocations a
  JOIN _matrix8 m
    ON a.conference_id = m.conference_id
   AND lower(btrim(a.country)) = lower(btrim(m.country))
)
SELECT allocation_id, code, NOW()
FROM ranked
WHERE rn = 1
ON CONFLICT (allocation_id) DO UPDATE
SET code = EXCLUDED.code,
    updated_at = EXCLUDED.updated_at
WHERE public.allocation_gate_codes.code IS DISTINCT FROM EXCLUDED.code;

COMMIT;
